from typing import List
import re

def _wrap_text_internal(text: str, width: int) -> List[str]:
    if width < 1:
        raise ValueError("width must be at least 1")
    text = re.sub(r'\s+', ' ', text).strip()
    if not text:
        return []
    words = text.split(' ')
    lines = []
    current_line = []
    current_length = 0
    for word in words:
        word_len = len(word)
        space_len = 1 if current_line else 0
        if current_length + space_len + word_len <= width:
            current_line.append(word)
            current_length += space_len + word_len
        else:
            if current_line:
                lines.append(' '.join(current_line))
            current_line = [word]
            current_length = word_len
    if current_line:
        lines.append(' '.join(current_line))
    return lines

def justify_text(text: str, width: int) -> List[str]:
    if width < 1:
        raise ValueError("width must be at least 1")

    lines = _wrap_text_internal(text, width)
    if not lines:
        return []

    justified_lines = []
    for i in range(len(lines)):
        line = lines[i]
        words = line.split(' ')

        if i == len(lines) - 1 or len(words) == 1 or len(line) > width:
            if len(line) <= width:
                justified_lines.append(line.ljust(width))
            else:
                justified_lines.append(line)
        else:
            total_chars = sum(len(w) for w in words)
            total_spaces_needed = width - total_chars
            gap_count = len(words) - 1
            spaces_per_gap = total_spaces_needed // gap_count
            extra_spaces = total_spaces_needed % gap_count

            res = []
            for j in range(gap_count):
                res.append(words[j])
                current_gap = spaces_per_gap + (1 if j < extra_spaces else 0)
                res.append(' ' * current_gap)
            res.append(words[-1])
            justified_lines.append(''.join(res))

    return justified_lines
