from typing import List
from .normalize_whitespace import normalize_whitespace

def split_sentences(text: str) -> List[str]:
    if not text:
        return []
    cleaned = normalize_whitespace(text)
    if not cleaned:
        return []

    words = cleaned.split(' ')
    abbs = {"Mr.", "Mrs.", "Ms.", "Dr.", "Prof.", "St.", "vs.", "e.g.", "i.e."}
    sentences = []
    current = []

    for i in range(len(words)):
        word = words[i]
        current.append(word)
        if i == len(words) - 1:
            break

        # Remove trailing quotes/brackets to find the actual end of the sentence
        stripped = word
        while stripped and stripped[-1] in "' )]":
            stripped = stripped[:-1]

        if not stripped or stripped[-1] not in ".!?":
            continue

        # Handle common abbreviations
        if word in abbs:
            continue

        # Handle initials: single uppercase letter followed by a period
        if stripped.endswith('.'):
            core = stripped[:-1]
            # Remove leading quotes/brackets from the core to check for the letter
            while core and core[0] in "'([":
